import{_ as e,o as a,c as d,a2 as r}from"./chunks/framework.RQXGjTIX.js";const o="/appliedcraftedenergistics/cell-style.png",g=JSON.parse('{"title":"气体存储元件","description":"","frontmatter":{},"headers":[],"relativePath":"guide/cells.md","filePath":"guide/cells.md"}'),l={name:"guide/cells.md"};function s(i,t,n,c,h,p){return a(),d("div",null,[...t[0]||(t[0]=[r('<h1 id="气体存储元件" tabindex="-1">气体存储元件 <a class="header-anchor" href="#气体存储元件" aria-label="Permalink to &quot;气体存储元件&quot;">​</a></h1><p>气体存储元件是 CCB 气体进入 ME 网络后的&quot;仓库&quot;。共五档：</p><table tabindex="0"><thead><tr><th>元件</th><th>AE 字节</th><th>气体容量</th><th>相当于 1 atm 下的体积</th></tr></thead><tbody><tr><td>1k</td><td>1,024</td><td><strong>1,024,000 GU</strong></td><td>1,024 m³</td></tr><tr><td>4k</td><td>4,096</td><td>4,096,000 GU</td><td>4,096 m³</td></tr><tr><td>16k</td><td>16,384</td><td>16,384,000 GU</td><td>16,384 m³</td></tr><tr><td>64k</td><td>65,536</td><td>65,536,000 GU</td><td>65,536 m³</td></tr><tr><td>256k</td><td>262,144</td><td>262,144,000 GU</td><td>262,144 m³</td></tr></tbody></table><p><img src="'+o+'" alt="气体元件与 AE2 元件样式对比"></p><p>换算契约：<strong>1 AE byte = 1,000 GU</strong>，而 <code>1 GU = 100 kPa 下的 1 升气体</code>。 所以元件容量（GU）除以 1,000 就是它占用的 AE 字节数，也等于&quot;多少立方米的常压气体&quot;。</p><h2 id="元件是什么、不是什么" tabindex="-1">元件是什么、不是什么 <a class="header-anchor" href="#元件是什么、不是什么" aria-label="Permalink to &quot;元件是什么、不是什么&quot;">​</a></h2><ul><li>元件<strong>只保存气体的数量</strong>，不保存气压；把同一只元件从 ME 驱动器里拿出来、放进去，气压不会&quot;变化&quot;， 因为它本来就没有气压这个概念。</li><li>元件不承担 CCB 的过压 / 破裂机制；气体进出网络的压力由 <a href="/appliedcraftedenergistics/guide/interface.html">ME 气体接口</a> 和 <a href="/appliedcraftedenergistics/guide/p2p.html">气体 P2P 隧道</a> 背后的真实容器负责。</li><li>每种气体都会占用一部分字节（与 AE2 流体元件一致），所以&quot;存得下多少种&quot;和&quot;存得下多少量&quot;是两回事。</li></ul><h2 id="放入网络" tabindex="-1">放入网络 <a class="header-anchor" href="#放入网络" aria-label="Permalink to &quot;放入网络&quot;">​</a></h2><p>把元件放进 <strong>ME 驱动器</strong>或 <strong>ME 箱子</strong>即可被网络读写。空元件可以用 AE2 的方式拆解回收。</p><h2 id="终端显示" tabindex="-1">终端显示 <a class="header-anchor" href="#终端显示" aria-label="Permalink to &quot;终端显示&quot;">​</a></h2><p>气体在终端里按气体名排序，图标是按气体颜色绘制的&quot;雾气&quot;图标，数量以 <strong>kGU</strong> 显示 （1 kGU = 1,000 GU）。与物品 / 流体混在同一个终端里，一次搜索即可。</p><h2 id="升级槽" tabindex="-1">升级槽 <a class="header-anchor" href="#升级槽" aria-label="Permalink to &quot;升级槽&quot;">​</a></h2><p>元件有 <strong>5 个升级槽</strong>，在<strong>元件工作台</strong>里安装：</p><ul><li>AE2 原生卡：反相卡、均分卡、溢出销毁卡；</li><li>气体专属卡：高压卡、扩容卡、多类型卡、安全阀卡。</li></ul><p>装卡后元件的<strong>字节上限</strong>会变化，因此终端里显示的容量会变大，这不代表元件&quot;降级&quot;—— 详见 <a href="/appliedcraftedenergistics/guide/upgrades.html">元件升级卡</a>。</p><div class="tip custom-block"><p class="custom-block-title">分区</p><p>和物品元件一样，气体元件也支持在元件工作台里填写分区。分区决定它接受哪些气体； 反相卡会反转分区列表的含义（白名单 ⇄ 黑名单）。</p></div>',16)])])}const m=e(l,[["render",s]]);export{g as __pageData,m as default};
